const data = $input.first().json;

// Compatibilidad con Webhook HTTP y MQTT Trigger.
let event = data;

if (data.body !== undefined) {
  event = data.body;
} else if (data.message !== undefined) {
  event = data.message;
} else if (data.payload !== undefined) {
  event = data.payload;
}

// MQTT puede entregar el mensaje como texto JSON.
if (typeof event === 'string') {
  try {
    event = JSON.parse(event);
  } catch (error) {
    return [{
      json: {
        send: false,
        reason: 'Mensaje JSON no válido',
        error: error.message
      }
    }];
  }
}

// Algunos nodos entregan el contenido como Buffer serializado.
if (event && event.type === 'Buffer' && Array.isArray(event.data)) {
  try {
    event = JSON.parse(
      Buffer.from(event.data).toString('utf8')
    );
  } catch (error) {
    return [{
      json: {
        send: false,
        reason: 'No se pudo interpretar el Buffer MQTT'
      }
    }];
  }
}

if (!event || typeof event !== 'object') {
  return [{
    json: {
      send: false,
      reason: 'Estructura de evento no válida'
    }
  }];
}

const capacity = Number(event.capacity);
const occupancy = Number(event.occupancy);
const validation = String(event.validation || 'ACEPTADO');
const eventId = String(event.eventId || 'SIN-ID');

if (
  !Number.isInteger(capacity) ||
  capacity <= 0 ||
  !Number.isInteger(occupancy) ||
  occupancy < 0 ||
  occupancy > capacity
) {
  return [{
    json: {
      send: false,
      reason: 'Datos de aforo invalidos',
      eventId,
      receivedKeys: Object.keys(event)
    }
  }];
}

const store = $getWorkflowStaticData('global');

const deviceId = String(event.deviceId || '').trim();
const sessionId = String(event.sessionId || '').trim();
const sequence = Number(event.sequence);

if (
  !/^[A-Za-z0-9_-]{1,80}$/.test(deviceId) ||
  !/^[A-Za-z0-9_.-]{1,80}$/.test(sessionId) ||
  !Number.isSafeInteger(sequence) ||
  sequence < 1
) {
  return [{ json: {
    send: false,
    reason: 'Identidad o secuencia de simulador no válida'
  }}];
}

store.sessions ??= {};
const sessionKey = deviceId + ':' + sessionId;
const sessionState = store.sessions[sessionKey] ??= {
  lastLevel: 'NORMAL',
  lastEventId: null,
  lastSequence: 0
};

if (sequence <= sessionState.lastSequence) {
  return [{ json: {
    send: false,
    reason: 'Evento duplicado o fuera de orden',
    deviceId,
    sessionId,
    sequence
  }}];
}

const level = occupancy >= capacity
  ? 'MAXIMO'
  : occupancy * 100 >= capacity * 80
    ? 'ADVERTENCIA'
    : 'NORMAL';

const previous = sessionState.lastLevel || 'NORMAL';
const invalid = validation === 'REVISAR_DATOS';

let message = '';

if (invalid) {
  message =
    `⚠️ Smart-Tourism: evento para revisión (${eventId}). ` +
    `Motivo: ${event.reason || 'NO_ESPECIFICADO'}. ` +
    `Aforo: ${occupancy}/${capacity}.`;

} else if (level !== previous) {

  if (level === 'MAXIMO') {
    message =
      `🚨 Smart-Tourism: CAPACIDAD MÁXIMA ` +
      `(${occupancy}/${capacity}). Restringir nuevos ingresos.`;

  } else if (level === 'ADVERTENCIA') {
    message =
      `⚠️ Smart-Tourism: aforo al ` +
      `${Math.round(occupancy * 100 / capacity)}% ` +
      `(${occupancy}/${capacity}).`;

  } else {
    message =
      `✅ Smart-Tourism: aforo normalizado ` +
      `(${occupancy}/${capacity}).`;
  }

}

// Evitar duplicados del mismo evento.
if (sessionState.lastEventId === eventId) {
  message = '';
}

sessionState.lastEventId = eventId;
sessionState.lastSequence = sequence;

if (message) {
  message =
    'Smart-Tourism | Simulador: ' + sessionId +
    ' | Dispositivo: ' + deviceId + '\n' +
    message;
}

// Mantener el estado anterior cuando el evento
// requiere revisión.
if (!invalid) {
  sessionState.lastLevel = level;
}

return [{
  json: {
    send: Boolean(message),
    message,
    eventId,
    deviceId,
    sessionId,
    occupancy,
    capacity,
    level,
    previous,
    validation,
    source: data.message !== undefined
      ? 'MQTT'
      : 'HTTP'
  }
}];
